import{_ as e,c as r,o as p,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"26、【大畜】 乾下艮上","description":"周易尚氏學 - 26、【大畜】 乾下艮上","frontmatter":{"title":"26、【大畜】 乾下艮上","description":"周易尚氏學 - 26、【大畜】 乾下艮上"},"headers":[],"relativePath":"classics/shangshi/031.md","filePath":"classics/shangshi/031.md"}'),s={name:"classics/shangshi/031.md"};function t(h,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_26、【大畜】-乾下艮上" tabindex="-1">26、【大畜】 乾下艮上 <a class="header-anchor" href="#_26、【大畜】-乾下艮上" aria-label="Permalink to “26、【大畜】 乾下艮上”">​</a></h1><p>乾為大。乾陽上升。為民所止。故日大畜。陽為艮畜。故利於貞定也。兌為食。艮為家。皆在外。故不家食吉。坤為大川。上居坤水之顛。下履重陰。得行其志。故曰利涉大川。與頤上九之利涉大川同也。</p><p>彖曰。大畜剛健篤實輝光。日新其德。剛上而尚賢。能止健。大正也。不家食吉。養賢也。利涉大川。應乎天也。剛健篤實。謂乾。輝光謂艮。艮為日。故曰日新。艮為君子。故曰尚賢。曰養賢。五天位。上孚於五。故曰應乎天。</p><p>象曰。天在山中。大畜。君子以多識前言往行。以畜其德。</p><p>識。論語女以為多學而識之者欽。注識記也。乾為前。為言。為行。為德。艮止於下。故多識前言往行。以畜其德。艮為君子。</p><p>初九。有厲。利已。</p><p>厲危也。已止也。初有應。似利往。然二三皆陽。遇敵。故曰有厲。初勿用。故利已。言往應四則有災也。舊解皆不知有厲之故在二三。於是虞氏命二變成坎。四在坎體。以取災象。經義之晦。至於如此。真可嘆也。</p><h3 id="象曰。有厲利已。不犯災也。" tabindex="-1">象曰。有厲利已。不犯災也。 <a class="header-anchor" href="#象曰。有厲利已。不犯災也。" aria-label="Permalink to “象曰。有厲利已。不犯災也。”">​</a></h3><p>不犯災。釋利已之故也。災即厲。指二三。</p><p>九二。輿說輹。</p><p>伏坤為輿。震為輹。二應在五。五震體。乃輿在內。轅（右復）在外。故曰輿脫輹。車之行全恃輹。輹脫則車不能行。二承乘皆陽。陽遇陽則窒。故有是象。舊說以二應五。便謂利涉大川指二者非也。如二能利涉。焉有此象哉。然爻辭無吉凶。無咎悔。故象曰中無尤。言無尤之故。以得中也。</p><h3 id="象曰。輿說輹。中無尤也。" tabindex="-1">象曰。輿說輹。中無尤也。 <a class="header-anchor" href="#象曰。輿說輹。中無尤也。" aria-label="Permalink to “象曰。輿說輹。中無尤也。”">​</a></h3><p>九三。艮馬逐。利艱貞。日閒輿衛。利有攸往。</p><p>乾為艮馬。震為逐。三多懼。故利艱貞。乾為日。爾雅釋詁。閒習也。詩秦風遊於北園。四馬即閒。傳亦訓閒為習。震為輿衛。日閒輿衛者。言車馬已閒習。利於行也。三臨重陰故行利。</p><h3 id="象曰。利有攸往。上合志也。" tabindex="-1">象曰。利有攸往。上合志也。 <a class="header-anchor" href="#象曰。利有攸往。上合志也。" aria-label="Permalink to “象曰。利有攸往。上合志也。”">​</a></h3><p>三遇重陰。陽遇陰則通。故曰上合志。上謂四五。此與升初六之上合志同。初六之上謂二三。陰遇陽則通。與陽遇陰同也。虞翻謂上為上爻。故易本一失。說無不誤。</p><p>六四。 童牛之牿 元吉。</p><p>釋文。童牛無角牛也。按太玄更次五雲。童牛角馬。不今不古。即謂牛無角也。牿釋文雲。陸作角。劉雲牿之言角也。九家作告。雲牛觸。角著橫木。所以告人。按劉陸作角者是也。駱牿角。音同通用。艮為牛。象失傳。詳焦氏易詁艮少故為童牛。而艮為角。四居艮初。有若初生之角。言小牛角初生也。四應初。故吉。</p><h3 id="象曰。六四元吉。有喜也。" tabindex="-1">象曰。六四元吉。有喜也。 <a class="header-anchor" href="#象曰。六四元吉。有喜也。" aria-label="Permalink to “象曰。六四元吉。有喜也。”">​</a></h3><p>應在初陽故有喜。廬浙雲。說文牿牛馬牢。牛在牢則範而不越。故吉。於艮止義亦合。</p><p>六五。豶豕之牙。吉。</p><p>爾雅釋獸。豕子橢（左豕）豶。注云。俗呼小豶豬為墮（左豕）子。是豶豕為小豕艮少象也。二兌為牙。五應之。故曰豶豕之牙。言小豕初生牙也。按艮為黔喙。獸之黔喙者莫過於豕。疑艮或有豕象。又姤以巽為豕。大畜三至五伏巽。或仍以巽為豕也。李鼎作深知豶豕二字皆由象生。然求之不得。謂五應二。二坎爻為豕。非。又廬浙雲坤雅以代（左木）系豕。謂之牙。牙者系之者也。系而不去故吉。亦與艮止義合。</p><h3 id="象日。六五之吉。有慶也。" tabindex="-1">象日。六五之吉。有慶也。 <a class="header-anchor" href="#象日。六五之吉。有慶也。" aria-label="Permalink to “象日。六五之吉。有慶也。”">​</a></h3><p>六五承陽。故有慶。晉六五。睽六五。皆上承陽。皆曰往有慶。茲與之同。</p><p>上九。何天之衢。亨。</p><p>艮一陽在上為天。又為背。故曰何。艮為道路。故曰何天之衢。左傳昭二年屍諸周氏之衢。注衢道也。又爾雅釋宮。四達謂之衢。何天之衢者。言陽在上不為所畜。通達之甚。象曰道大行。亦釋衢為道。大行即謂其通達。虞翻釋何為當，王弼竟釋何為何乃。朱子取之。益非。蓋皆以天衢如何負何為疑。豈知易辭皆攝取象之精神。而不能執其解。執則易辭無一可通。</p><h3 id="象曰。何天之衢。道大行也。" tabindex="-1">象曰。何天之衢。道大行也。 <a class="header-anchor" href="#象曰。何天之衢。道大行也。" aria-label="Permalink to “象曰。何天之衢。道大行也。”">​</a></h3><p>艮為天。易林豫之旅雲。人天門。隨之蹇雲戴瓶望天。皆以艮為天。</p>',28)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
